const agentResult =
  $json || {};

let agentContext;

try {
  agentContext =
    $('Prepare Agent Context')
      .item
      .json;
} catch {
  /*
  Fallback: select the Prepare Agent Context output
  from the same run index.
  */
  const sameRunItems =
    $('Prepare Agent Context')
      .all(
        0,
        $runIndex
      );

  agentContext =
    sameRunItems[0]?.json;
}

if (!agentContext) {
  throw new Error(
    'Prepare Parsing Input could not resolve the current Agent context.'
  );
}

const rawSteps =
  Array.isArray(
    agentResult.intermediateSteps
  )
    ? agentResult.intermediateSteps
    : [];

const compactSteps =
  rawSteps.map(
    (step, index) => {
      const toolName =
        step.action?.tool ||
        step.tool ||
        step.toolName ||
        `Tool ${index + 1}`;

      const toolInput =
        step.action?.toolInput ||
        step.toolInput ||
        {};

      const observation =
        step.observation ??
        step.output ??
        step.result ??
        '';

      let compactObservation;

      if (
        typeof observation ===
        'string'
      ) {
        compactObservation =
          observation.length > 3000
            ? observation.slice(
                0,
                3000
              )
            : observation;
      } else {
        const serialized =
          JSON.stringify(
            observation
          );

        compactObservation =
          serialized.length > 3000
            ? serialized.slice(
                0,
                3000
              )
            : serialized;
      }

      return {
        order:
          index + 1,

        tool:
          String(toolName),

        input:
          toolInput,

        observation:
          compactObservation,
      };
    }
  );

return [
  {
    json: {
      case_run_id:
        agentContext.case_run_id,

      submission_version:
        agentContext.submission_version,

      assessment_cycle:
        agentContext.assessment_cycle,

      next_required_check:
        agentContext.next_required_check,

      agent_output:
        agentResult.output ||
        agentResult.text ||
        '',

      compact_intermediate_steps:
        compactSteps,

      raw_agent_result:
        agentResult,
    },
  },
];

