const chainResult =
  $json || {};

let parsingInput;

try {
  parsingInput =
    $('Prepare Parsing Input')
      .item
      .json;
} catch {
  const sameRunItems =
    $('Prepare Parsing Input')
      .all(
        0,
        $runIndex
      );

  parsingInput =
    sameRunItems[0]?.json;
}

if (!parsingInput) {
  throw new Error(
    'Could not resolve the current parsing input.'
  );
}

let provisional =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  provisional &&
  typeof provisional ===
    'object' &&
  !Array.isArray(provisional) &&
  provisional.output !== undefined
) {
  provisional =
    provisional.output;
}

if (
  typeof provisional ===
  'string'
) {
  const cleaned =
    provisional
      .trim()
      .replace(
        /^```json\s*/i,
        ''
      )
      .replace(
        /^```\s*/i,
        ''
      )
      .replace(
        /\s*```$/i,
        ''
      );

  provisional =
    JSON.parse(cleaned);
}

const allowedOutcomes = [
  'APPROVE',
  'REJECT',
  'NEED_MORE_INFORMATION',
  'MANUAL_REVIEW',
];

let provisionalOutcome =
  String(
    provisional
      .provisional_outcome ||
    ''
  )
    .trim()
    .toUpperCase()
    .replace(
      /\s+/g,
      '_'
    );

if (
  !allowedOutcomes.includes(
    provisionalOutcome
  )
) {
  provisionalOutcome =
    'MANUAL_REVIEW';
}

function stringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(item =>
      typeof item === 'string'
        ? item.trim()
        : JSON.stringify(item)
    )
    .filter(Boolean);
}

const rawConfidence =
  Number(
    provisional.confidence
  );

const confidence =
  Number.isFinite(rawConfidence)
    ? Math.max(
        0,
        Math.min(
          1,
          rawConfidence
        )
      )
    : 0;

return [
  {
    json: {
      case_run_id:
        parsingInput.case_run_id,

      submission_version:
        parsingInput.submission_version,

      assessment_cycle:
        parsingInput.assessment_cycle,

      provisional_recommendation: {
        case_run_id:
          parsingInput.case_run_id,

        tools_called:
          stringArray(
            provisional.tools_called
          ),

        provisional_outcome:
          provisionalOutcome,

        evidence_summary:
          stringArray(
            provisional
              .evidence_summary
          ),

        missing_information:
          stringArray(
            provisional
              .missing_information
          ),

        conflicts:
          stringArray(
            provisional.conflicts
          ),

        human_review_required:
          provisional
            .human_review_required ===
            true ||
          provisionalOutcome ===
            'MANUAL_REVIEW',

        next_action:
          String(
            provisional.next_action ||
            ''
          ),

        decision_rationale:
          String(
            provisional
              .decision_rationale ||
            ''
          ),

        confidence,
      },

      intermediate_steps:
        parsingInput
          .compact_intermediate_steps,
    },
  },
];

/*
============================================================
BUILD CHAT RESPONSE
============================================================

Purpose:
- Create one clean, client-facing response.
- Never expose raw prompts, tool JSON, rule objects, or debug data.
- De-duplicate completed checks by check_type.
- Supplement missing check names from the visible tool trace without
  falsely claiming that an unknown check passed.
- Translate technical queue/reason codes into readable language.
============================================================
*/

const result =
  $input.first()?.json || {};

/*
------------------------------------------------------------
HELPER FUNCTIONS
------------------------------------------------------------
*/

function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function toBoolean(value) {
  return (
    value === true ||
    String(value)
      .trim()
      .toLowerCase() === 'true' ||
    String(value)
      .trim()
      .toUpperCase() === 'YES'
  );
}

function normaliseList(value) {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return [];
  }

  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'object') {
    return [value];
  }

  const text =
    String(value).trim();

  if (!text) {
    return [];
  }

  /*
  Support JSON-array strings.
  */
  if (
    text.startsWith('[') &&
    text.endsWith(']')
  ) {
    try {
      const parsed =
        JSON.parse(text);

      if (Array.isArray(parsed)) {
        return parsed;
      }
    } catch {
      // Fall through to delimiter parsing.
    }
  }

  return text
    .split(/\s*;\s*|\r?\n+/)
    .map(item => item.trim())
    .filter(Boolean);
}

function uniqueStrings(values) {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const text =
      String(value || '').trim();

    if (!text) {
      continue;
    }

    const key =
      text.toUpperCase();

    if (!seen.has(key)) {
      seen.add(key);
      output.push(text);
    }
  }

  return output;
}

function titleCaseCode(value) {
  return String(value || '')
    .trim()
    .replace(/_/g, ' ')
    .toLowerCase()
    .replace(
      /\b\w/g,
      character =>
        character.toUpperCase()
    );
}

function timestamp(value) {
  const parsed =
    Date.parse(
      String(value || '')
    );

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

/*
Convert either a check code or a Workflow Tool name into the
canonical check_type used by the decision model.
*/
function canonicalCheckType(value) {
  let rawValue = value;

  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    rawValue =
      firstNonEmpty(
        value.check_type,
        value.Check_Type,
        value.tool,
        value.tool_name,
        value.toolName,
        value.name,
        value.utility_name,
        value.Utility_Name
      );
  }

  const upper =
    String(rawValue || '')
      .trim()
      .toUpperCase()
      .replace(/[\s-]+/g, '_');

  if (!upper) {
    return '';
  }

  if (
    upper.includes(
      'DOCUMENT'
    )
  ) {
    return 'DOCUMENT_EXTRACTION';
  }

  if (
    upper.includes(
      'BUSINESS'
    )
  ) {
    return 'BUSINESS_VALIDATION';
  }

  if (
    upper.includes(
      'IDENTITY'
    )
  ) {
    return 'IDENTITY_VALIDATION';
  }

  if (
    upper.includes(
      'AUTHORITY'
    )
  ) {
    return 'AUTHORITY_VALIDATION';
  }

  if (
    upper.includes(
      'SYSTEM'
    ) ||
    upper.includes(
      'CRM'
    ) ||
    upper.includes(
      'PARTY_DATA'
    )
  ) {
    return 'SYSTEM_DATA_CHECK';
  }

  if (
    upper.includes(
      'FINANCIAL'
    ) ||
    upper.includes(
      'CREDIT'
    ) ||
    upper.includes(
      'BAD_DEBT'
    )
  ) {
    return 'FINANCIAL_CHECK';
  }

  if (
    upper.includes(
      'FINAL'
    ) ||
    upper.includes(
      'COMPLIANCE'
    ) ||
    upper.includes(
      'AVCV'
    )
  ) {
    return 'FINAL_VERIFICATION';
  }

  return upper;
}

/*
------------------------------------------------------------
DISPLAY CONFIGURATION
------------------------------------------------------------
*/

const checkNameMap = {
  DOCUMENT_EXTRACTION:
    'Document checks',

  BUSINESS_VALIDATION:
    'Business validation',

  IDENTITY_VALIDATION:
    'Identity validation',

  AUTHORITY_VALIDATION:
    'Authority validation',

  SYSTEM_DATA_CHECK:
    'System-data checks',

