function normaliseCheck(
  rawCheck,
  fallbackIndex
) {
  if (
    rawCheck === undefined ||
    rawCheck === null
  ) {
    return null;
  }

  if (
    typeof rawCheck === 'string'
  ) {
    const checkType =
      canonicalCheckType(
        rawCheck
      );

    if (!checkType) {
      return null;
    }

    return {
      check_type:
        checkType,

      status:
        'EXECUTED',

      sequence:
        checkSequenceMap[
          checkType
        ] ??
        fallbackIndex,

      rule_ids:
        [],

      reason_codes:
        [],

      created_at:
        '',
    };
  }

  const checkType =
    canonicalCheckType(
      rawCheck
    );

  if (!checkType) {
    return null;
  }

  const status =
    String(
      firstNonEmpty(
        rawCheck.status,
        rawCheck.Status,
        'EXECUTED'
      )
    )
      .trim()
      .toUpperCase();

  return {
    ...rawCheck,

    check_type:
      checkType,

    status,

    sequence:
      Number(
        firstNonEmpty(
          rawCheck.sequence,
          rawCheck.Sequence,
          checkSequenceMap[
            checkType
          ],
          fallbackIndex
        )
      ),

    rule_ids:
      normaliseList(
        firstNonEmpty(
          rawCheck.rule_ids,
          rawCheck.Rule_IDs
        )
      ).map(item =>
        String(item).trim()
      ),

    reason_codes:
      normaliseList(
        firstNonEmpty(
          rawCheck.reason_codes,
          rawCheck.Reason_Codes
        )
      ).map(item =>
        String(item).trim()
      ),

    created_at:
      String(
        firstNonEmpty(
          rawCheck.created_at,
          rawCheck.Created_At
        )
      ).trim(),
  };
}

function shouldReplaceCheck(
  existing,
  candidate
) {
  const existingHasEvidencePass =
    existing.rule_ids.includes(
      'EVID-001'
    );

  const candidateHasEvidencePass =
    candidate.rule_ids.includes(
      'EVID-001'
    );

  /*
  An accepted-evidence PASS must replace an earlier
  inconclusive result for the same check.
  */
  if (
    candidateHasEvidencePass &&
    !existingHasEvidencePass
  ) {
    return true;
  }

  if (
    existingHasEvidencePass &&
    !candidateHasEvidencePass
  ) {
    return false;
  }

  const existingTime =
    timestamp(
      existing.created_at
    );

  const candidateTime =
    timestamp(
      candidate.created_at
    );

  if (
    candidateTime !==
    existingTime
  ) {
    return (
      candidateTime >
      existingTime
    );
  }

  const existingRank =
    statusMeta[
      existing.status
    ]?.rank ?? 0;

  const candidateRank =
    statusMeta[
      candidate.status
    ]?.rank ?? 0;

  /*
  If timestamps aren't available, retain the more
  consequential status. For exact duplicates, the
  later candidate replaces the earlier one.
  */
  return (
    candidateRank >=
    existingRank
  );
}

const completedChecksByType =
  new Map();

rawCompletedChecks.forEach(
  (rawCheck, index) => {
    const normalisedCheck =
      normaliseCheck(
        rawCheck,
        index + 1
      );

    if (!normalisedCheck) {
      return;
    }

    const existing =
      completedChecksByType.get(
        normalisedCheck.check_type
      );

    if (
      !existing ||
      shouldReplaceCheck(
        existing,
        normalisedCheck
      )
    ) {
      completedChecksByType.set(
        normalisedCheck.check_type,
        normalisedCheck
