function extractResponse(input) {
  const candidates = [
    input.response,
    input.text,
    input.chatInput,
    input.message,
    input.answer,
    input.data?.response,
    input.data?.text,
    input.data?.message,
    input.data,
  ];

  for (const candidate of candidates) {
    if (
      candidate !== undefined &&
      candidate !== null
    ) {
      if (typeof candidate === 'string') {
        return candidate.trim();
      }

      if (typeof candidate === 'object') {
        const nested =
          candidate.response ??
          candidate.text ??
          candidate.message ??
          candidate.answer;

        if (typeof nested === 'string') {
          return nested.trim();
        }
      }
    }
  }

  return '';
}

const response =
  extractResponse($json || {});

const upper =
