}

if (!caseRunId) {
  throw new Error(
    'Cannot build upload URL: case_run_id is missing.'
  );
}

const evidenceUploadUrl =
  formProductionUrl +
  '?evidence_request_id=' +
  encodeURIComponent(
    evidenceRequestId
  ) +
  '&case_run_id=' +
  encodeURIComponent(
    caseRunId
  );

return [
  {
    json: {
      ...request,

      evidence_request_id:
        evidenceRequestId,

      case_run_id:
        caseRunId,

      evidence_upload_url:
        evidenceUploadUrl,
    },
  },
];

function extractReply(input) {
  const candidates = [
    input.response,
    input.text,
    input.chatInput,
    input.message,
    input.answer,
    input.data?.response,
    input.data?.text,
    input.data?.message,
    input.data,
  ];

  for (const candidate of candidates) {
    if (
      candidate === undefined ||
      candidate === null
    ) {
      continue;
    }

    if (typeof candidate === 'string') {
      return candidate.trim();
    }

    if (typeof candidate === 'object') {
      const nested =
        candidate.response ??
        candidate.text ??
        candidate.message ??
        candidate.answer;

      if (typeof nested === 'string') {
        return nested.trim();
      }
    }
  }

  return '';
}

const reply =
  extractReply($json || {});

const normalizedReply =
  reply
    .trim()
    .toUpperCase();

const request =
  $('Build Evidence Upload Link')
    .last()
    .json;

return [
  {
    json: {
      evidence_request_id:
        request.evidence_request_id,

      case_run_id:
        request.case_run_id,

      submission_version:
        request.submission_version,

      evidence_upload_url:
        request.evidence_upload_url,

      customer_reply:
        reply,

      normalized_reply:
        normalizedReply,

      customer_cancelled:
        [
          'CANCEL',
          'STOP',
          'END',
          'CANCEL REQUEST',
        ].includes(
          normalizedReply
        ),

      upload_acknowledged:
        [
          'UPLOADED',
          'DONE',
          'SUBMITTED',
          'COMPLETE',
          'COMPLETED',
        ].includes(
          normalizedReply
        ),
    },
  },
];

const rows =
  $input
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.evidence_id || ''
      ).trim()
    );

const request =
  $('Normalise Upload Reply')
    .last()
    .json;

const usableRows =
  rows.filter(row => {
    const status =
      String(
        row.validation_status || ''
      )
        .trim()
        .toUpperCase();

    return ![
      'REJECTED',
      'SUPERSEDED',
    ].includes(status);
  });

return [
  {
    json: {
      evidence_request_id:
        request.evidence_request_id,

      case_run_id:
        request.case_run_id,

      submission_version:
        request.submission_version,

      evidence_available:
        usableRows.length > 0,

      evidence_count:
        usableRows.length,

      evidence_ids:
        usableRows
          .map(row =>
            row.evidence_id
          )
          .filter(Boolean),

      customer_reply:
        request.customer_reply,
    },
  },
];

const governed =
  $json || {};

let provisionalEnvelope;

try {
  provisionalEnvelope =
    $('Normalise Provisional Recommendation')
      .item
      .json;
} catch {
  const sameRunItems =
    $('Normalise Provisional Recommendation')
      .all(
        0,
        $runIndex
      );

  provisionalEnvelope =
    sameRunItems[0]?.json;
}

if (!provisionalEnvelope) {
  throw new Error(
    'Could not resolve the provisional recommendation for the current assessment cycle.'
  );
}

const provisional =
  provisionalEnvelope
    .provisional_recommendation;

const provisionalOutcome =
  String(
    provisional
      .provisional_outcome ||
    ''
  ).toUpperCase();

const governedOutcome =
  String(
    governed.outcome || ''
  ).toUpperCase();

const governanceOverride =
  provisionalOutcome !==
  governedOutcome;

return [
  {
    json: {
      ...governed,

      assessment_cycle:
        provisionalEnvelope
          .assessment_cycle,

      provisional_recommendation:
        provisional,

      provisional_outcome:
        provisionalOutcome,

      governed_outcome:
        governedOutcome,

      governance_override:
        governanceOverride,

      governance_override_message:
        governanceOverride
          ? (
              `The AI Agent recommended ${provisionalOutcome}, ` +
              `but deterministic policy recorded ${governedOutcome}.`
            )
          : (
              'The AI Agent recommendation and deterministic policy outcome are aligned.'
            ),

      visible_tool_trace:
        provisional
          .tools_called || [],

      provisional_rationale:
        provisional
          .decision_rationale || '',

      provisional_confidence:
        provisional
          .confidence ?? null,
    },
  },
];
